def bonus_q(
    env,
    episodes=500,
    alpha=0.5,
    gamma=0.9,
    epsilon=0.1,
    bonus=1.0,
    power=0.5,
    seed=0,
    max_steps=1000,
) -> dict:
    """访问次数塑形奖励的 Q 学习，返回键序 q、counts 的 dict。

    Q、N 域序同 replay_q_learning 的 q：覆盖从 S 可达的非 G 格与
    U/R/D/L 的全部组合，键序为坐标升序 × URDL，初始分别为 0.0、0，
    两表互相独立。每回合 reset，done 即停；单回合最多 max_steps 步，
    到达步限截断时末步 done=False 仍照常自举更新。

    每个真实步先且仅调用一次 rng.random()，小于 epsilon 时再按 URDL
    调用 rng.randrange(4) 探索，否则取 URDL 中首个最大 Q 动作。step
    后先 N[s,a]+=1，令 b = bonus / N[s,a]**power；done 时目标为
    reward+b，否则目标为 reward+b+gamma*max_a Q[next,a]，随后
    Q[s,a] += alpha*(目标-Q[s,a])。b、目标或新 Q 非有限即抛
    ValueError。全部随机性来自一个 random.Random(seed)。
    """
    if not isinstance(env, GridWorld):
        raise TypeError("env must be a GridWorld")
    if isinstance(episodes, bool) or not isinstance(episodes, int):
        raise TypeError("episodes must be an int")
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise TypeError("seed must be an int")
    if isinstance(max_steps, bool) or not isinstance(max_steps, int):
        raise TypeError("max_steps must be an int")
    if isinstance(alpha, bool) or not isinstance(alpha, (int, float)):
        raise TypeError("alpha must be an int or float")
    if isinstance(gamma, bool) or not isinstance(gamma, (int, float)):
        raise TypeError("gamma must be an int or float")
    if isinstance(epsilon, bool) or not isinstance(epsilon, (int, float)):
        raise TypeError("epsilon must be an int or float")
    if isinstance(bonus, bool) or not isinstance(bonus, (int, float)):
        raise TypeError("bonus must be an int or float")
    if isinstance(power, bool) or not isinstance(power, (int, float)):
        raise TypeError("power must be an int or float")
    if episodes <= 0:
        raise ValueError("episodes must be positive")
    if max_steps <= 0:
        raise ValueError("max_steps must be positive")
    if not _is_finite_number(alpha) or alpha <= 0 or alpha > 1:
        raise ValueError("alpha must be finite and in (0, 1]")
    if not _is_finite_number(gamma) or gamma < 0 or gamma >= 1:
        raise ValueError("gamma must be finite and in [0, 1)")
    if not _is_finite_number(epsilon) or epsilon < 0 or epsilon > 1:
        raise ValueError("epsilon must be finite and in [0, 1]")
    try:
        bonus = float(bonus)
    except OverflowError:
        raise ValueError("bonus must convert to a finite float")
    try:
        power = float(power)
    except OverflowError:
        raise ValueError("power must convert to a finite float")
    if not math.isfinite(bonus) or bonus < 0.0:
        raise ValueError("bonus must be finite and non-negative")
    if not math.isfinite(power) or power <= 0.0 or power > 1.0:
        raise ValueError("power must be finite and in (0, 1]")

    actions = tuple(_ACTIONS)  # U, R, D, L
    states = sorted(
        state
        for state in _reachable_cells(env)
        if env._cell(state) != "G"
    )
    q = {(state, action): 0.0 for state in states for action in actions}
    counts = {(state, action): 0 for state in states for action in actions}
    rng = random.Random(seed)

    for _ in range(episodes):
        state = env.reset()
        for _ in range(max_steps):
            if rng.random() < epsilon:
                action = actions[rng.randrange(4)]
            else:
                action = max(actions, key=lambda a: q[(state, a)])
            next_state, reward, done = env.step(action)
            key = (state, action)
            counts[key] += 1
            try:
                b = bonus / counts[key] ** power
            except OverflowError:
                raise ValueError("bonus value must remain finite")
            if not math.isfinite(b):
                raise ValueError("bonus value must remain finite")
            if done:
                target = reward + b
            else:
                target = reward + b + gamma * max(
                    q[(next_state, a)] for a in actions
                )
            new_q = q[key] + alpha * (target - q[key])
            if not math.isfinite(target) or not math.isfinite(new_q):
                raise ValueError("Q value must remain finite")
            q[key] = new_q
            if done:
                break
            state = next_state
    return {"q": q, "counts": counts}


def prioritized_replay_q(
    env,
    episodes=500,
    alpha=0.5,
    gamma=0.9,
    epsilon=0.1,
    beta=0.4,
    seed=0,
) -> dict:
    """按比例的优先经验回放 Q 学习，返回
    {"q": Q, "buffer": 缓冲副本, "priorities": float 列表, "updates": int}。

    契约同 replay_q_learning（容量固定 1000、每步回放 4 次、单回合至多
    1000 步，末步照常入缓冲并回放），差异如下。缓冲并行维护同序优先级
    列表：追加时若缓冲已满（长度达到 1000），同步删首行与首优先级；
    新项优先级取现存优先级最大值，无旧项取 1.0。每次回放重算
    w_i = priority_i ** 0.6，以一次 rng.random() * sum(w) 取样，累计值
    首个严格大于样本者命中，均不大于则取末项。P_i = w_i / sum(w)，
    重要度 I_i = (N * P_i) ** (-beta) 后除以全部 I 的最大值归一，仅以
    命中项的归一 I 作 Q += alpha * I * delta，其中
    delta = reward + (done 时 0，否则 gamma * maxQ(next)) - Q（按当前
    Q 计算），随后命中项优先级置为 abs(delta) + 1e-6。任何运算溢出或
    非有限结果均抛 ValueError。全部随机性来自一个 random.Random(seed)。
    """
    if not isinstance(env, GridWorld):
        raise TypeError("env must be a GridWorld")
    if isinstance(episodes, bool) or not isinstance(episodes, int):
        raise TypeError("episodes must be an int")
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise TypeError("seed must be an int")
    if isinstance(alpha, bool) or not isinstance(alpha, (int, float)):
        raise TypeError("alpha must be an int or float")
    if isinstance(gamma, bool) or not isinstance(gamma, (int, float)):
        raise TypeError("gamma must be an int or float")
